  private setupSonarInput() {
    // Keyboard: F key activates sonar
    document.addEventListener('keydown', (e: KeyboardEvent) => {
      if (e.code === 'KeyF' && this.state === 'playing') {
        this.activateSonar();
      }
    });
  }

  private setupShipCallbacks() {
    this.shipSystem.onShipDocked = (_shipType: number, points: number) => {
      if (this.state !== 'playing') return;
      // Increment combo
      this.combo++;
      this.comboDecayTimer = 8.0; // 8 second window to maintain combo
      this.comboMultiplier = 1.0 + Math.min(this.combo - 1, 9) * 0.25; // Max 3.5x at 10 combo
      const comboPoints = Math.floor(points * this.comboMultiplier);
      this.score += comboPoints;
      if (this.combo > this.maxCombo) this.maxCombo = this.combo;

      // Show combo notification
      if (this.combo >= 2) {
        this.audioSystem.playComboChime(this.combo);
        this.hudPanel?.getElementById('wave-start-info')?.setProperties({
          text: `COMBO x${this.combo} — ${this.comboMultiplier.toFixed(1)}x multiplier! +${comboPoints}`,
        });
        this.showingWaveStart = true;
        this.waveStartTimer = 2.0;
      }
    };

    this.shipSystem.onShipCrashed = () => {
      if (this.state !== 'playing') return;
      // Break combo
      if (this.combo >= 2) {
        this.hudPanel?.getElementById('wave-start-info')?.setProperties({
          text: `COMBO BROKEN — x${this.combo} streak lost!`,
        });
        this.showingWaveStart = true;
        this.waveStartTimer = 2.0;
      }
      this.combo = 0;
      this.comboMultiplier = 1.0;
      this.comboDecayTimer = 0;
    };
  }

  private activateSonar() {
    if (!this.sonarReady || this.state !== 'playing') return;
    // Costs 20% beam energy to use sonar
    const energy = this.lighthouseSystem.getBeamEnergy();
    if (energy < this.lighthouseSystem.getMaxEnergy() * 0.15) return;

    this.sonarReady = false;
    this.sonarCooldown = this.sonarCooldownMax;
    this.lastSonarRadius = 0;

    this.envSystem.triggerSonar();
    this.audioSystem.playSonarPing();
    this.audioSystem.playFoghorn();

    this.hudPanel?.getElementById('wave-start-info')?.setProperties({
      text: '\ud83d\udce1 SONAR PULSE \u2014 Ships revealed!',
    });
    this.showingWaveStart = true;
    this.waveStartTimer = 2.0;
  }

  private triggerTidalWave() {
    if (Math.random() > 0.7) {
      this.tidalTimer = 15 + Math.random() * 20;
      return; // didn't trigger
    }
    this.tidalActive = true;
    this.tidalDuration = 3.0;
    const angle = Math.random() * Math.PI * 2;
    this.shipSystem.setTidalForce(Math.cos(angle) * 4, Math.sin(angle) * 4);
    this.audioSystem.playTidalWave();
    this.envSystem.triggerTidalSurge();
    this.hudPanel?.getElementById('wave-start-info')?.setProperties({
      text: '\ud83c\udf0a TIDAL WAVE \u2014 Ships pushed off course!',
    });
    this.showingWaveStart = true;
    this.waveStartTimer = 3.0;
    this.tidalTimer = 20 + Math.random() * 25;
  }

  private tryUpgrade(type: 'range' | 'width' | 'energy') {
    const cost = 300;
    if (this.score < cost) return;
    this.score -= cost;
    this.audioSystem.playUpgradeSound();

    if (type === 'range') {
      this.lighthouseSystem.upgradeRange();
    } else if (type === 'width') {
      this.lighthouseSystem.upgradeWidth();
    } else {
      this.lighthouseSystem.upgradeCapacity();
    }

    this.updateUpgradePanel();
  }

